export const ART_BY_ID: Record<string, SymbolArt> = Object.fromEntries(SYMBOL_ART.map((art) => [art.id, art]));

const TRANSPORT_ART: { test: RegExp; id: string }[] = [
  { test: /forklift\s*sb\s*empty/i, id: 'materials-forklift-sb-empty' },
  { test: /forklift\s*sb\s*full/i, id: 'materials-forklift-sb-full' },
  { test: /tugger\s*cart|ro-?ro|\bbr\b/i, id: 'materials-tugger-cart-transfer-br-ro-ro' },
  { test: /tugger/i, id: 'materials-tugger-train-transfer-shelf-carts' },
  { test: /sequenc/i, id: 'materials-sequenced-cart-transfer' },
  { test: /forklift|cariste/i, id: 'materials-forklift-transfer' },
  { test: /push\s*cart|\bcart\b|chariot/i, id: 'materials-push-cart-transfer' },
  { test: /\bagc\b|\bagv\b/i, id: 'materials-agc-transfer' },
  { test: /\bmanual\b|\bman\b|manuel/i, id: 'materials-man-transfer' },
  { test: /truck|camion/i, id: 'materials-truck-transfer' },
];

/** Drawing for a transport word typed in the flow register, such as Truck or Forklift. */
export function transportArtwork(label: string) {
  const word = label.trim();
  const match = TRANSPORT_ART.find((item) => item.test.test(word));
  return match ? ART_BY_ID[match.id] : undefined;
}

const NUMBER = /-?\d+(?:\.\d+)?/g;
const boundsCache = new WeakMap<SymbolArt, { x: number; y: number; width: number; height: number }>();

/** The drawing itself, without the empty margin stored around the spreadsheet artwork. */
export function artBounds(art: SymbolArt) {
  const cached = boundsCache.get(art);
  if (cached) return cached;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  const take = (x: number, y: number) => {
    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
  };
  for (const path of art.paths) {
    const nums = path.d.match(NUMBER);
    if (!nums) continue;
    for (let index = 0; index + 1 < nums.length; index += 2) take(Number(nums[index]), Number(nums[index + 1]));
  }
  for (const image of art.images ?? []) {
    take(image.x, image.y);
    take(image.x + image.width, image.y + image.height);
  }
  const bounds =
    !Number.isFinite(minX) || maxX <= minX || maxY <= minY
      ? { x: 0, y: 0, width: Math.max(art.width, 1), height: Math.max(art.height, 1) }
      : { x: minX, y: minY, width: maxX - minX, height: maxY - minY };
  boundsCache.set(art, bounds);
  return bounds;
}

export function artBox(art: SymbolArt) {
  const bounds = artBounds(art);
  let scale = 132 / Math.max(bounds.width, bounds.height);
  if (Math.min(bounds.width, bounds.height) * scale < 28) scale = 28 / Math.min(bounds.width, bounds.height);
  return { width: Math.round(bounds.width * scale), height: Math.round(bounds.height * scale) };
}
